-- 2) 레시피 구분 정보
ALTER TABLE recipes ADD COLUMN recipe_code VARCHAR(20) NULL;           -- 데이터 원본 코드 (B/L/D = 정제본, Q = LLM 아침)
ALTER TABLE recipes ADD COLUMN meal_slot VARCHAR(20) NULL;             -- BREAKFAST / LUNCH_DINNER. NULL이면 meal_type 기준(기존 레시피)
ALTER TABLE recipes ADD COLUMN dish_type VARCHAR(50) NULL;             -- 요리 형태 (예: 현미 덮밥, 간장 달걀밥)
ALTER TABLE recipes ADD COLUMN dish_group VARCHAR(100) NULL;           -- 같은 요리의 변형 묶음. 연속 추천 방지용
ALTER TABLE recipes ADD COLUMN recommendation_reason VARCHAR(300) NULL;
ALTER TABLE recipes ADD CONSTRAINT uk_recipes_recipe_code UNIQUE (recipe_code);
ALTER TABLE recipes ADD CONSTRAINT ck_recipes_meal_slot CHECK (meal_slot IS NULL OR meal_slot IN ('BREAKFAST','LUNCH_DINNER'));
CREATE INDEX idx_recipes_source_meal_slot ON recipes (source, meal_slot);

